// Function node (Parse JSON)
const out = [];

/** Recopila todos los strings dentro del objeto (busca en keys/arrays) */
function collectStrings(obj, acc = []) {
  if (obj == null) return acc;
  if (typeof obj === 'string') { acc.push(obj); return acc; }
  if (Array.isArray(obj)) {
    for (const v of obj) collectStrings(v, acc);
  } else if (typeof obj === 'object') {
    for (const k of Object.keys(obj)) collectStrings(obj[k], acc);
  }
  return acc;
}

/** Extrae una subcadena JSON balanceada (soporta { ... } y [ ... ]).
 *  Devuelve null si no encuentra cierre balanceado. */
function extractBalanced(s) {
  const start = s.search(/[{[]/);
  if (start === -1) return null;
  const open = s[start];
  const close = open === '{' ? '}' : ']';
  let depth = 0;
  let inString = false;
  let prev = '';
  for (let i = start; i < s.length; i++) {
    const ch = s[i];
    if (ch === '"' && prev !== '\\') inString = !inString;
    if (!inString) {
      if (ch === open) depth++;
      else if (ch === close) {
        depth--;
        if (depth === 0) return s.slice(start, i + 1);
      }
    }
    prev = ch;
  }
  // Si aquí no está balanceado, intenta devolver hasta la última llave/corchete
  const lastClose = s.lastIndexOf(close);
  if (lastClose > start) return s.slice(start, lastClose + 1);
  return null;
}

/** Intento de parse seguro */
function tryJSONParse(s) {
  try { return JSON.parse(s); } catch (e) { return null; }
}

// ---- comienzo ----
const item = items[0] ? items[0].json : {};
const candidates = collectStrings(item);

// Si no hay strings, usa la representación JSON del objeto
const rawCandidate = (candidates.length ? candidates : [JSON.stringify(item)]).sort((a,b) => {
  // Prioriza candidatos que contengan "temas" y llaves
  const score = s => (s.includes('"temas"') ? 10 : 0) + (s.includes('{') ? 1 : 0);
  return score(b) - score(a);
})[0];

let parsed = null;

// 1) intenta extraer bloque balanceado y parsear
const balanced = extractBalanced(rawCandidate);
if (balanced) parsed = tryJSONParse(balanced);

// 2) si falla, intenta "unescape" de \n y \"
if (!parsed) {
  const unesc = rawCandidate.replace(/\\n/g, '\n').replace(/\\"/g, '"');
  const balanced2 = extractBalanced(unesc) || unesc;
  parsed = tryJSONParse(balanced2);
}

// 3) si aún falla, busca la clave "temas" y recorta desde la llave previa
if (!parsed) {
  const keyIdx = rawCandidate.search(/"temas"\s*:/);
  if (keyIdx !== -1) {
    const braceIdx = rawCandidate.lastIndexOf('{', keyIdx);
    if (braceIdx !== -1) {
      const substr = rawCandidate.slice(braceIdx);
      const balanced3 = extractBalanced(substr) || substr;
      parsed = tryJSONParse(balanced3);
    }
  }
}

// 4) salida: si parseó, devuelve el objeto; si no, devuelve raw para debug
if (!parsed) {
  out.push({
    json: {
      success: false,
      error: 'No se pudo parsear JSON. Revisa el campo raw para depuración.',
      raw: rawCandidate
    }
  });
  return out;
}

// Si parseó correctamente, devolvemos el objeto (ej: { temas: [...] })
out.push({ json: parsed });
return out[0].json.temas.map(t => ({ json: t }));

let rows = [];

for (const item of items) {

  const seccion = item.json;     // cada sección viene separada
  const nombre = seccion.nombre || "";

  // regla de plantilla
  let plantilla = 2;
  if (nombre.toLowerCase() === "portada") plantilla = 8;
  if (nombre.toLowerCase() === "trivia") plantilla = 10;

  for (const sub of seccion.subtemas || []) {

    const subNombre = sub.nombre || "";


    if (!sub.contenido || sub.contenido.length === 0) {
      rows.push({
        seccion: nombre,
        subseccion: subNombre,
        slide: 1,
        plantilla
      });
      continue;
    }


    sub.contenido.forEach((texto, index) => {
      const slide = index + 1;

      rows.push({
        seccion: index === 0 ? nombre : "",
        subseccion: index === 0 ? subNombre : "",
        slide,
        plantilla
      });
    });

  }

}

// Regresar cada fila como item
return rows.map(r => ({ json: r }));

// Entrada: items (cada item.json: row_number, seccion, subseccion, slide, plantilla, titulo/prompt)
// Salida: lista de items: [{json:{...}}, {json:{...}}, ...]

const rows = items
  .map(i => i.json)
  .sort((a, b) => (a.row_number || 0) - (b.row_number || 0));

// Ejemplo: const temaPortada = $json.tema;
const temaPortada = $('Obtener campos del formulario').first().json.inf_tema;

const seccionesMap = {};
let currentSection = null;
let currentSubtopic = null;

for (const row of rows) {
  const seccion = (row.seccion || "").trim();
  const subseccion = (row.subseccion || "").trim();

  // Nueva sección
  if (seccion) {
    if (!seccionesMap[seccion]) {
      seccionesMap[seccion] = { nombre: seccion, subtemas: [] };
    }

    currentSection = seccionesMap[seccion];

    // Mantener prompt y título si vienen del sheet
    if (row.prompt) currentSection.prompt = row.prompt;
    if (row.titulo) currentSection.titulo = row.titulo;
    if (row.title) currentSection.titulo = row.title;

    currentSubtopic = null;
  }

  // Nueva subsección (slide 1)
  if (subseccion) {
    if (!currentSection) continue;

    currentSubtopic = { nombre: subseccion };

    if (row.titulo) currentSubtopic.titulo = row.titulo;
    if (row.title) currentSubtopic.titulo = row.title;

    // Solo agregar contenido si no es Portada o Trivia
    if (
      currentSection.nombre.toLowerCase() !== "portada" &&
      currentSection.nombre.toLowerCase() !== "trivia"
    ) {
      currentSubtopic.contenido = [""];
    }

    currentSection.subtemas.push(currentSubtopic);
    continue;
  }

  // Fila sin sección ni subsección → slides adicionales
  if (!seccion && !subseccion) {
    if (!currentSubtopic) continue;

    if (
      currentSection.nombre.toLowerCase() !== "portada" &&
      currentSection.nombre.toLowerCase() !== "trivia"
    ) {
      currentSubtopic.contenido.push("");
    }
  }
}

// ---- POSTPROCESO PORTADA ----
if (seccionesMap["Portada"]) {
  const portada = seccionesMap["Portada"];
  const sub = portada.subtemas[0];

  // Portada no lleva contenido
  if (sub) {
    delete sub.contenido;
  }

  // Insertar el título correcto proveniente del nodo externo
  if (sub) {
    sub.titulo = temaPortada;
  }

  // Generar prompt 100% correcto basado en ese título
  portada.prompt = `Genera una imagen en formato PNG, no texto, solo imagen, sobre el tema ${temaPortada}. No incluyas ninguna descripción, solo devuelve la imagen.`;
}

// ---- POSTPROCESO TRIVIA ----
if (seccionesMap["Trivia"]) {
  const trivia = seccionesMap["Trivia"];
  const sub = trivia.subtemas[0];

  if (sub) {
    delete sub.contenido;
    delete sub.titulo;
  }
}

// ---- GENERAR LISTA ORDENADA ----
const output = [];

// Portada primero
if (seccionesMap["Portada"]) {
  output.push({ json: seccionesMap["Portada"] });
}

// Otras secciones
for (const nombre of Object.keys(seccionesMap)) {
  if (nombre === "Portada" || nombre === "Trivia") continue;
  output.push({ json: seccionesMap[nombre] });
}

// Trivia última
if (seccionesMap["Trivia"]) {
  output.push({ json: seccionesMap["Trivia"] });
}

return output;

